#define ISECT_EPSILON 0.1
#define ITER_COUNT 10.f

struct Ray {
    vec3 origin;
    vec3 dir;
    float t;
};


float sphereSDF(vec3 p, float s) {
    return length(p) - s;
}

float sceneSDF(vec3 p) {
    return sphereSDF(p, 0.2f);
}

vec3 SDF_Normal(vec3 query) {
    vec2 epsilon = vec2(0.0, 0.001);
    return normalize( vec3( sceneSDF(query + epsilon.yxx) - sceneSDF(query - epsilon.yxx),
                            sceneSDF(query + epsilon.xyx) - sceneSDF(query - epsilon.xyx),
                            sceneSDF(query + epsilon.xxy) - sceneSDF(query - epsilon.xxy)));
}

float rayMarch(Ray ray) {
    float dist = 0.f;
    float iterations = 1.f;
    vec3 currentPosition = ray.origin + ray.dir * dist;
    while (iterations < ITER_COUNT) {
        dist = sceneSDF(currentPosition);
        if (dist < ISECT_EPSILON) {
            return dist;
        }
        currentPosition += ray.dir * dist;
        iterations++;
    }
    return -1.f;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    Ray ray;
    ray.origin = vec3(0, 1.0, 3.0);

    vec3 refPoint = vec3(0.0, 0.0, 0.0);
    vec3 camLook = normalize(refPoint - ray.origin);
    vec3 camRight = normalize(cross(camLook, vec3(0.f, 1.f, 0.f)));
    vec3 camUp = normalize(cross(camRight, camLook));

    vec2 screenPoint = (2.0 * fragCoord.xy - iResolution.xy) / iResolution.y;
    vec3 rayPoint = refPoint + screenPoint.x * camRight + screenPoint.y * camUp;
    ray.dir = normalize(rayPoint - ray.origin);

    ray.t = rayMarch(ray);
    if (ray.t == -1.f) {
        discard;
    }

    vec3 nor = SDF_Normal(rayPoint + ray.dir * ray.t);
    fragColor = vec4(0.5 * (nor + vec3(1.)), 1.);

}
